INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT141-S4-Q4$batch10$, 141, 4, 4, $batch10$Method$batch10$, $batch10$Psychologist: Some have argued that Freudian psychotherapy is the most effective kind because it is so difficult and time consuming. But surely this does not follow. Similar reasoning—e.g., concluding that a car-repair chain has the most effective technique for repairing cars because the cars it services receive so much work and spend so much time in the shop—would never be accepted.$batch10$, $batch10$The reasoning technique employed by the psychologist is that of attempting to undermine an argument by$batch10$, $batch10$C$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=141 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT141-S4-Q4$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$introducing a principle that contradicts the one on which the argument is based$batch10$, $batch10$Not Described$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT141-S4-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$questioning the truth of its premises$batch10$, $batch10$Not Described$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT141-S4-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$presenting an analogous argument whose conclusion is thought to be obviously false$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT141-S4-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$claiming that the argument is based on a false analogy$batch10$, $batch10$Not Described$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT141-S4-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$suggesting that a supposed cause of a phenomenon is actually an effect of that phenomenon$batch10$, $batch10$Not Described$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT141-S4-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT141-S4-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$The argument that Freudian therapy is most effective because it is difficult and time consuming doesn't follow.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The same reasoning would conclude that a car-repair chain is the most effective because the cars it services get so much work and spend so much time in the shop, and no one would accept that.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The psychologist doesn't attack the premises. The psychologist builds an argument with the same structure (takes lots of work and time, so it must be most effective) whose conclusion is plainly unacceptable. If the copy fails, so does the original.$batch10$), (3, $batch10$Goal$batch10$, $batch10$The psychologist presents a parallel argument with an obviously false conclusion.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT141-S4-Q4$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$The psychologist never offers a competing principle. The attack is through a parallel example.$batch10$), ($batch10$B$batch10$, $batch10$The psychologist doesn't question that Freudian therapy is difficult and time consuming. The attack is on the inference.$batch10$), ($batch10$C$batch10$, $batch10$The car-repair argument has the same structure as the Freudian argument, and its conclusion is one "that would never be accepted." Undermining an argument with a parallel that leads to an obviously false conclusion is exactly this.$batch10$), ($batch10$D$batch10$, $batch10$The original argument doesn't use an analogy. The psychologist is the one who introduces the comparison.$batch10$), ($batch10$E$batch10$, $batch10$The psychologist never says the difficulty is caused by effectiveness. There's no reversal of cause and effect.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT141-S4-Q4$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
